 * Per-key state machines for the two policy kinds. Each keeps one
 * independent state per key, created lazily the first time that key reaches
 * the policy.
 */

/**
 * A token bucket. Tokens are tracked as an integer numerator over a fixed
 * denominator of `per`, so a refill of `refill` tokens every `per` ticks
 * advances the numerator by exactly `refill` per tick with no rounding.
 */
export class TokenBucket {
  constructor(definition) {
    this.capacity = definition.capacity
    this.refill = definition.refill
    this.per = definition.per
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { tick: null, numerator: this.capacity * this.per }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    if (state.tick === null) {
      state.tick = tick
      return
    }
    const elapsed = tick - state.tick
    const full = this.capacity * this.per
    const grown = state.numerator + this.refill * elapsed
    state.numerator = grown > full ? full : grown
    state.tick = tick
  }

  allows(key) {
    return this.#state(key).numerator >= this.per
  }

  record(key) {
    this.#state(key).numerator -= this.per
  }
}

/**
 * A sliding window. Remembers the ticks of the requests it recorded for a
 * key, forgetting any that fall at or before `tick - span` each time it
 * advances.
 */
export class SlidingWindow {
  constructor(definition) {
    this.limit = definition.limit
    this.span = definition.span
    this.states = new Map()
  }

  #state(key) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    const threshold = tick - this.span
    state.ticks = state.ticks.filter((remembered) => remembered > threshold)
  }

  allows(key) {
    return BigInt(this.#state(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.#state(key).ticks.push(tick)
  }
}

/**
 * Builds the runtime policy instances (with their own per-key state) from
 * the declarations a limiter file parsed to.
 */
export function buildPolicies(declarations) {
  const policies = new Map()
  for (const [name, definition] of declarations) {
    policies.set(name, definition.kind === 'bucket' ? new TokenBucket(definition) : new SlidingWindow(definition))
  }
  return policies
}
"}

