 * Runs a parsed limiter file's events against its policies, producing one
 * verdict per event in log order.
 */
import { buildPolicies } from './policies.js'

/**
 * Finds the route whose prefix the key starts with and which is longest
 * among those that match. Returns `null` when no route matches.
 */
function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

/**
 * Replays every event, returning `{ tick, key, allow, policyName }` verdicts
 * in the same order the events appeared. `policyName` is set only when
 * `allow` is false, naming the first policy on the route that refused.
 */
export function simulate({ policies: declarations, routes, events }) {
  const policies = buildPolicies(declarations)
  const verdicts = []

  for (const { tick, key } of events) {
    const route = findRoute(routes, key)
    const routePolicies = route ? route.policyNames.map((name) => policies.get(name)) : []

    for (const policy of routePolicies) policy.advance(key, tick)

    let deniedBy = null
    for (let i = 0; i < routePolicies.length; i++) {
      if (!routePolicies[i].allows(key)) {
        deniedBy = route.policyNames[i]
        break
      }
    }

    if (deniedBy === null) {
      for (const policy of routePolicies) policy.record(key, tick)
      verdicts.push({ tick, key, allow: true })
    } else {
      verdicts.push({ tick, key, allow: false, policyName: deniedBy })
    }
  }

  return verdicts
}
"}

