  if (mode !== 'replay' && mode !== 'summary') {
    fail('usage: cli.js replay|summary')
  }

  const input = readFileSync(0, 'utf8')

  let parsed
  try {
    parsed = parseLimiterFile(input)
  } catch (error) {
    if (error instanceof LimiterError) fail(`line ${error.line}: ${error.message}`)
    throw error
  }

  const verdicts = simulate(parsed)

  if (mode === 'replay') {
    const lines = verdicts.map((verdict) =>
      verdict.allow ? `${verdict.tick} ${verdict.key} allow` : `${verdict.tick} ${verdict.key} deny ${verdict.policyName}`
    )
    process.stdout.write(lines.map((line) => `${line}\n`).join(''))
    return
  }

  const totals = new Map()
  let totalAllowed = 0
  let totalDenied = 0
  for (const verdict of verdicts) {
    let counts = totals.get(verdict.key)
    if (!counts) {
      counts = { allowed: 0, denied: 0 }
      totals.set(verdict.key, counts)
    }
    if (verdict.allow) {
      counts.allowed++
      totalAllowed++
    } else {
      counts.denied++
      totalDenied++
    }
  }

  const keys = [...totals.keys()].sort()
  const lines = keys.map((key) => {
    const counts = totals.get(key)
    return `${key} allowed=${counts.allowed} denied=${counts.denied}\n`
  })
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  process.stdout.write(lines.join(''))
}

main()
